import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        double x = scanner.nextDouble();
        double y = scanner.nextDouble();
        double n = scanner.nextDouble();
        double min_diff = 2e9;
        double ratio = x / y;
        long best_a = 0;
        long best_i = 1;
        for (double i = 1; i <= n; i++) {
            long a = (long) (ratio * i + 0.4999);
            double diff = Math.abs((double) a / i - ratio);
            if (diff < min_diff) {
                min_diff = diff;
                best_a = a;
                best_i = (long) i;
            }
        }
        System.out.println(best_a + "/" + best_i);
        scanner.close();
    }
}
